package org.ruralnet.graph;

import org.junit.jupiter.api.Test;
import java.math.BigDecimal;
import java.util.*;
import static org.junit.jupiter.api.Assertions.*;

class GraphAlgorithmsTest {
  private static GraphSnapshot.Edge e(int id,UUID a,UUID b,String d,String c){return new GraphSnapshot.Edge(new UUID(0,id),a,b,new BigDecimal(d),new BigDecimal(c),BigDecimal.TEN,"ACTIVE");}
  @Test void computesMatchingMinimumForestsAcrossDisconnectedGraph(){UUID a=new UUID(0,1),b=new UUID(0,2),c=new UUID(0,3),d=new UUID(0,4),z=new UUID(0,5);var g=new GraphSnapshot(List.of(n(a),n(b),n(c),n(d),n(z)),List.of(e(1,a,b,"2","2"),e(2,b,c,"3","3"),e(3,a,c,"4","4"),e(4,c,d,"1","5")),1);var k=GraphAlgorithms.kruskal(g);var p=GraphAlgorithms.prim(g);assertEquals(2,k.components());assertEquals(g.nodes().size()-k.components(),k.edges().size());assertEquals(0,k.totalCost().compareTo(p.totalCost()));assertEquals(0,k.totalCost().compareTo(new BigDecimal("10")));assertTrue(k.isolatedNodeIds().contains(z));}
  @Test void findsRoutesAndReportsUnreachableDestinations(){UUID a=new UUID(0,1),b=new UUID(0,2),c=new UUID(0,3),z=new UUID(0,5);var g=new GraphSnapshot(List.of(n(a),n(b),n(c),n(z)),List.of(e(1,a,b,"2","2"),e(2,b,c,"3","3"),e(3,a,c,"4","4")),1);var route=GraphAlgorithms.dijkstra(g,a,c,"DISTANCE");assertTrue(route.reachable());assertEquals(List.of(a,c),route.nodeIds());assertEquals(0,route.totalDistanceKm().compareTo(new BigDecimal("4")));assertFalse(GraphAlgorithms.dijkstra(g,a,z,"COST").reachable());}
  @Test void identifiesBridgeAndArticulationPoint(){UUID a=new UUID(0,1),b=new UUID(0,2),c=new UUID(0,3),d=new UUID(0,4);var first=e(1,a,b,"1","1");var bridge=e(2,b,c,"1","1");var last=e(3,c,d,"1","1");var result=GraphAlgorithms.criticality(new GraphSnapshot(List.of(n(a),n(b),n(c),n(d)),List.of(first,bridge,last),1));assertEquals(List.of(first.id(),bridge.id(),last.id()),result.bridgeEdgeIds());assertEquals(List.of(b,c),result.articulationNodeIds());}
  @Test void demonstrationFixtureIncludesDisconnectedComponentAndKnownBottlenecks(){UUID[] ids=new UUID[14];List<GraphSnapshot.Node> ns=new ArrayList<>();for(int i=0;i<ids.length;i++){ids[i]=new UUID(0,i+1);ns.add(n(ids[i]));}int[][] pairs={{0,1},{1,2},{2,3},{3,4},{4,0},{0,5},{2,6},{1,7},{4,9},{5,10},{6,11},{7,12},{8,13},{10,11},{6,10}};List<GraphSnapshot.Edge> es=new ArrayList<>();for(int i=0;i<pairs.length;i++){var e=e(i+1,ids[pairs[i][0]],ids[pairs[i][1]],"4",i<5?"10000":"20000");if(i>=13)e=new GraphSnapshot.Edge(e.id(),e.a(),e.b(),e.distanceKm(),e.cost(),e.capacity(),"PLANNED");es.add(e);}var g=new GraphSnapshot(ns,es,3);var active=new GraphSnapshot(ns,g.activeEdges(),3);var forest=GraphAlgorithms.kruskal(active);var critical=GraphAlgorithms.criticality(active);assertEquals(2,forest.components());assertEquals(12,forest.edges().size());assertTrue(critical.bridgeEdgeIds().contains(es.get(5).id()));assertTrue(critical.articulationNodeIds().contains(ids[5]));assertTrue(GraphAlgorithms.dijkstra(active,ids[0],ids[10],"DISTANCE").reachable());assertFalse(GraphAlgorithms.dijkstra(active,ids[0],ids[8],"COST").reachable());}
  private static GraphSnapshot.Node n(UUID id){return new GraphSnapshot.Node(id,id.toString(),id.toString(),"VILLAGE",0,0);}
}
